import pathlib, zipfile, shutil, sys

out_dir = pathlib.Path('/filesystem/final_batch4__mechanical_task5_pcw_flush_mop__blind/output')
zip_path = pathlib.Path('/filesystem/final_batch4__mechanical_task5_pcw_flush_mop__blind/output/submission.zip')
