import ezdxf, glob, os

base = "/filesystem/final_batch4__mechanical_task5_pcw_flush_mop__blind"
os.chdir(base)

for f in sorted(glob.glob("drawings/*.dxf")):
    print(f"\n==================== {f} ====================")
    doc = ezdxf.readfile(f)
    msp = doc.modelspace()
    texts = []
    for e in msp:
        if e.dxftype() == "TEXT":
            texts.append((round(e.dxf.insert.y, 1), round(e.dxf.insert.x, 1), e.dxf.layer, e.dxf.text))
        elif e.dxftype() == "MTEXT":
            texts.append((round(e.dxf.insert.y, 1), round(e.dxf.insert.x, 1), e.dxf.layer, e.text))
        elif e.dxftype() == "INSERT":
            attribs = {a.dxf.tag: a.dxf.text for a in e.attribs}
            texts.append((round(e.dxf.insert.y, 1), round(e.dxf.insert.x, 1), e.dxf.layer, f"BLOCK:{e.dxf.name} {attribs}"))
    for y, x, lay, t in sorted(texts, key=lambda item: (-item[0], item[1])):
        print(f"  ({x:6.1f}, {y:6.1f}) [{lay}] {t}")
